function sizePool(ratePerSec, holdMs) {
  // Little's law: connections = rate (per second) * hold time (seconds)
  const demand = ratePerSec * holdMs;   // BUG: holdMs is milliseconds, not seconds
  return Math.floor(demand);             // BUG: under-provisioning is worse than over
}

